SELECT city.ID AS CITY_ID, city.CITY_NAME, city.TIMEZONE, ss.ID AS SUNRISE_SUNSET_ID, ss.date, ss.sunrise_time, ss.sunset_time, ss.day_length_minutes FROM world_clock_city city LEFT JOIN world_clock_sunrise_sunset ss ON city.ID = SS.CITY_ID WHERE city.LOGIC_DEL = 0 and ss.LOGIC_DEL = 0 AND ss.DATE = DATE(#{dto.date})
AND ss.CITY_ID = #{dto.id}
AND city.CITY_NAME IN
#{item}
